import * as React from 'react';
import { DashboardLayout } from './components/DashboardLayout';
import { Header } from './components/Header';
import { MetricCards } from './components/MetricCards';
import ChartsSection from './components/ChartsSection';
import RecentActivity from './components/RecentActivity';
import { Sidebar } from './components/Sidebar';
import {
  activityItems,
  categoryDistributionData,
  metrics,
  navigationItems,
  trendData,
  type NavigationItem,
} from './data/dashboardData';

/** Header copy derived from the selected dashboard navigation item. */
interface HeaderContent {
  /** Primary page title shown in the dashboard header. */
  title: string;
  /** Supporting description for the currently selected section. */
  subtitle: string;
  /** Additional static context shown with the header. */
  supportInfo: string;
}

/**
 * Builds navigation data with the selected item marked as active.
 */
function buildNavigationItems(selectedNavId: string): NavigationItem[] {
  const normalizedSelectedNavId: string = selectedNavId.trim();
  const hasSelectedMatch: boolean = navigationItems.some(
    (item: NavigationItem): boolean => item.id === normalizedSelectedNavId,
  );

  return navigationItems.map(
    (item: NavigationItem): NavigationItem => ({
      ...item,
      isActive: hasSelectedMatch
        ? item.id === normalizedSelectedNavId
        : item.isActive === true,
    }),
  );
}

/**
 * Returns the initial selected navigation id from the local dashboard seed data.
 */
function getInitialSelectedNavId(): string {
  const activeItem: NavigationItem | undefined = navigationItems.find(
    (item: NavigationItem): boolean => item.isActive === true && item.id.trim().length > 0,
  );

  if (activeItem) {
    return activeItem.id;
  }

  const firstValidItem: NavigationItem | undefined = navigationItems.find(
    (item: NavigationItem): boolean => item.id.trim().length > 0,
  );

  return firstValidItem ? firstValidItem.id : '';
}

/**
 * Returns presentation copy for the current dashboard section.
 */
function getHeaderContent(selectedNavId: string): HeaderContent {
  const normalizedSelectedNavId: string = selectedNavId.trim();
  const selectedItem: NavigationItem | undefined = navigationItems.find(
    (item: NavigationItem): boolean => item.id === normalizedSelectedNavId,
  );

  const label: string = selectedItem?.label ?? 'Dashboard';
  const description: string =
    selectedItem?.description ?? 'Operational insights for your team.';

  return {
    title: label,
    subtitle: description,
    supportInfo:
      'All dashboard data is rendered locally with no routing, background sync, or network requests.',
  };
}

/**
 * App renders the single dashboard page and keeps all interaction state local.
 */
export default function App(): React.JSX.Element {
  const [selectedNavId, setSelectedNavId] = React.useState<string>(getInitialSelectedNavId);

  const selectedNavigationItems: NavigationItem[] = React.useMemo(
    (): NavigationItem[] => buildNavigationItems(selectedNavId),
    [selectedNavId],
  );

  const headerContent: HeaderContent = React.useMemo(
    (): HeaderContent => getHeaderContent(selectedNavId),
    [selectedNavId],
  );

  const handleNavigationSelect = React.useCallback((itemId: string): void => {
    const normalizedItemId: string = itemId.trim();

    if (!normalizedItemId) {
      return;
    }

    setSelectedNavId(normalizedItemId);
  }, []);

  return (
    <DashboardLayout
      sidebar={
        <Sidebar
          items={selectedNavigationItems}
          selectedItemId={selectedNavId}
          onSelect={handleNavigationSelect}
        />
      }
      header={
        <Header
          title={headerContent.title}
          subtitle={headerContent.subtitle}
          supportInfo={headerContent.supportInfo}
        />
      }
      metrics={<MetricCards metrics={metrics} />}
      charts={<ChartsSection trendData={trendData} categoryData={categoryDistributionData} />}
      activity={<RecentActivity items={activityItems} />}
    />
  );
}

